using System.Security.Claims;
using BrewNest.Contracts.Procurement;
using BrewNest.Modules.Procurement.Application.Interfaces;
using BrewNest.Modules.Procurement.Domain.Entities;
using BrewNest.Modules.Procurement.Infrastructure.Persistence;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
namespace BrewNest.Modules.Procurement.Application.Services;
internal enum ProcurementResultStatus{Success,Validation,NotFound,Conflict,Forbidden}
internal sealed record ProcurementResult<T>(ProcurementResultStatus Status,T? Value,string[] Errors){public bool Succeeded=>Status==ProcurementResultStatus.Success;public static ProcurementResult<T> Success(T value)=>new(ProcurementResultStatus.Success,value,[]);public static ProcurementResult<T> Fail(ProcurementResultStatus status,params string[] errors)=>new(status,default,errors);}
internal sealed record ProcurementContext(string Actor,string[] Roles){public static ProcurementContext From(HttpContext h)=>new(h.User.FindFirstValue(ClaimTypes.NameIdentifier)??h.User.Identity?.Name??"anonymous",h.User.FindAll(ClaimTypes.Role).Select(x=>x.Value).ToArray());}
internal sealed partial class ProcurementService(ProcurementDbContext db,IProcurementCatalogPort catalog,IProcurementApprovalPolicyPort approvals,IProcurementInventoryPort inventory,IProcurementDocumentNumbers numbers,TimeProvider clock,ILogger<ProcurementService> logger)
{
    [LoggerMessage(EventId=501,Level=LogLevel.Warning,Message="Procurement concurrency conflict in {EntityTypes}")]
    private static partial void LogConcurrency(ILogger logger,Exception exception,string entityTypes);
    private DateTimeOffset Now=>clock.GetUtcNow();
    public async Task<ProcurementResult<ProcurementReferenceData>> References(CancellationToken t)=>ProcurementResult<ProcurementReferenceData>.Success(await catalog.GetReferencesAsync(t));
    public async Task<ProcurementResult<RequisitionResponse[]>> Requisitions(CancellationToken t)=>ProcurementResult<RequisitionResponse[]>.Success((await db.Requisitions.AsNoTracking().Include(x=>x.Lines).OrderByDescending(x=>x.CreatedAt).ToArrayAsync(t)).Select(Map).ToArray());
    public async Task<ProcurementResult<RfqResponse[]>> Rfqs(CancellationToken t)=>ProcurementResult<RfqResponse[]>.Success((await db.Rfqs.AsNoTracking().Include(x=>x.Vendors).OrderByDescending(x=>x.CreatedAt).ToArrayAsync(t)).Select(Map).ToArray());
    public async Task<ProcurementResult<QuotationResponse[]>> Quotations(Guid? rfqId,CancellationToken t){var q=db.Quotations.AsNoTracking().Include(x=>x.Lines).AsQueryable();if(rfqId is not null)q=q.Where(x=>x.RfqId==rfqId);return ProcurementResult<QuotationResponse[]>.Success((await q.OrderBy(x=>x.Status).ThenBy(x=>x.Lines.Sum(y=>y.Quantity*y.UnitPrice)).ToArrayAsync(t)).Select(Map).ToArray());}
    public async Task<ProcurementResult<PurchaseOrderResponse[]>> Orders(CancellationToken t)=>ProcurementResult<PurchaseOrderResponse[]>.Success((await db.PurchaseOrders.AsNoTracking().AsSplitQuery().Include(x=>x.Lines).Include(x=>x.Approvals).OrderByDescending(x=>x.CreatedAt).ToArrayAsync(t)).Select(Map).ToArray());
    public async Task<ProcurementResult<GoodsReceiptResponse[]>> Receipts(CancellationToken t)
    {
        var receipts = await db.GoodsReceipts.AsNoTracking().Include(x => x.Lines)
            .OrderByDescending(x => x.CreatedAt).ToArrayAsync(t);
        var returned = await db.VendorReturns.AsNoTracking().SelectMany(x => x.Lines)
            .GroupBy(x => x.GoodsReceiptLineId)
            .Select(group => new { Id = group.Key, Quantity = group.Sum(x => x.Quantity) })
            .ToDictionaryAsync(x => x.Id, x => x.Quantity, t);
        return ProcurementResult<GoodsReceiptResponse[]>.Success(receipts.Select(x => Map(x, returned)).ToArray());
    }
    public async Task<ProcurementResult<ProcurementStatusHistoryResponse[]>> History(CancellationToken t)=>ProcurementResult<ProcurementStatusHistoryResponse[]>.Success((await db.StatusHistory.AsNoTracking().OrderByDescending(x=>x.ChangedAt).Take(500).ToArrayAsync(t)).Select(x=>new ProcurementStatusHistoryResponse(x.Id,x.DocumentType,x.DocumentId,x.PreviousStatus,x.NewStatus,x.Reason,x.ChangedBy,x.ChangedAt)).ToArray());
    public async Task<ProcurementResult<RequisitionResponse>> CreateRequisition(CreateRequisitionRequest r,ProcurementContext c,CancellationToken t){var e=Validate(r);if(e.Length>0)return Validation<RequisitionResponse>(e);foreach(var line in r.Lines)if(await catalog.GetItemAsync(line.ItemId,t) is null)return Validation<RequisitionResponse>("A selected material is inactive or unavailable in Catalog. Refresh the item list and try again.");var x=new PurchaseRequisition{Id=Guid.NewGuid(),Number=numbers.Requisition(),Department=r.Department.Trim(),RequiredOn=r.RequiredOn,Reason=r.Reason.Trim(),Status=PrStatus.Draft,CreatedAt=Now,CreatedBy=c.Actor};foreach(var l in r.Lines)x.Lines.Add(new(){Id=Guid.NewGuid(),RequisitionId=x.Id,ItemId=l.ItemId,Quantity=l.Quantity,EstimatedUnitPrice=l.EstimatedUnitPrice,Notes=l.Notes.Trim()});db.Requisitions.Add(x);History("Requisition",x.Id,"None",x.Status.ToString(),"Created",c);return await Save(()=>Map(x),t);}
    public async Task<ProcurementResult<RequisitionResponse>> ChangeRequisition(Guid id,string action,ChangeProcurementStatusRequest r,ProcurementContext c,CancellationToken t){var x=await db.Requisitions.Include(y=>y.Lines).SingleOrDefaultAsync(y=>y.Id==id,t);if(x is null)return NotFound<RequisitionResponse>();if(!Version(x.RowVersion,r.Version))return Conflict<RequisitionResponse>("The requisition changed. Reload and retry.");var old=x.Status;if(action=="submit"&&x.Status==PrStatus.Draft)x.Status=PrStatus.Submitted;else if(action=="approve"&&x.Status==PrStatus.Submitted){var route=await approvals.ResolveAsync("PurchaseRequisition",null,t);if(route is null)return Conflict<RequisitionResponse>("No active Purchase Requisition approval policy is configured.");if(!route.Steps.Any(s=>HasRole(c,s.RequiredRole)))return Forbidden<RequisitionResponse>("Your role cannot approve this requisition.");x.Status=PrStatus.Approved;}else if(action=="reject"&&x.Status==PrStatus.Submitted)x.Status=PrStatus.Rejected;else return Conflict<RequisitionResponse>("The requested requisition transition is not allowed.");Touch(x,c);History("Requisition",x.Id,old.ToString(),x.Status.ToString(),r.Reason,c);return await Save(()=>Map(x),t);}
    public async Task<ProcurementResult<RfqResponse>> CreateRfq(CreateRfqRequest r,ProcurementContext c,CancellationToken t){var pr=await db.Requisitions.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==r.RequisitionId,t);if(pr is null)return NotFound<RfqResponse>();if(pr.Status!=PrStatus.Approved)return Conflict<RfqResponse>("Only an approved requisition can become an RFQ.");if(r.VendorIds.Length==0||r.VendorIds.Distinct().Count()!=r.VendorIds.Length)return Validation<RfqResponse>("Select at least one unique vendor.");var refs=await catalog.GetReferencesAsync(t);if(r.VendorIds.Except(refs.Vendors.Select(x=>x.Id)).Any())return Validation<RfqResponse>("One or more vendors are inactive or unknown.");var x=new RequestForQuotation{Id=Guid.NewGuid(),Number=numbers.Rfq(),RequisitionId=pr.Id,ResponseDeadline=r.ResponseDeadline,Status="Issued",CreatedAt=Now,CreatedBy=c.Actor};foreach(var vendor in r.VendorIds)x.Vendors.Add(new(){Id=Guid.NewGuid(),RfqId=x.Id,VendorId=vendor});pr.Status=PrStatus.Converted;db.Rfqs.Add(x);History("RFQ",x.Id,"Draft","Issued","RFQ issued",c);return await Save(()=>Map(x),t);}
    public async Task<ProcurementResult<QuotationResponse>> SubmitQuotation(Guid rfqId,SubmitQuotationRequest r,ProcurementContext c,CancellationToken t){var rfq=await db.Rfqs.AsSplitQuery().Include(x=>x.Vendors).Include(x=>x.Requisition).ThenInclude(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==rfqId,t);if(rfq is null)return NotFound<QuotationResponse>();if(!rfq.Vendors.Any(x=>x.VendorId==r.VendorId))return Validation<QuotationResponse>("The vendor was not invited to this RFQ.");if(r.Lines.Length==0||r.Lines.Any(x=>x.Quantity<=0||x.UnitPrice<0||x.LeadTimeDays<0)||r.Lines.Select(x=>x.ItemId).Order().SequenceEqual(rfq.Requisition.Lines.Select(x=>x.ItemId).Order())==false)return Validation<QuotationResponse>("Quote every requested item with valid quantities, prices, and lead time.");var vendor=(await catalog.GetReferencesAsync(t)).Vendors.Single(x=>x.Id==r.VendorId);var x=new VendorQuotation{Id=Guid.NewGuid(),Number=$"QUOTE-{Guid.NewGuid():N}"[..18],RfqId=rfqId,VendorId=r.VendorId,VendorName=vendor.Name,ValidUntil=r.ValidUntil,Reference=r.Reference.Trim(),Status=QuoteStatus.Received,CreatedAt=Now,CreatedBy=c.Actor};foreach(var l in r.Lines)x.Lines.Add(new(){Id=Guid.NewGuid(),QuotationId=x.Id,ItemId=l.ItemId,Quantity=l.Quantity,UnitPrice=l.UnitPrice,LeadTimeDays=l.LeadTimeDays});db.Quotations.Add(x);return await Save(()=>Map(x),t);}
    public async Task<ProcurementResult<PurchaseOrderResponse>> SelectQuotation(Guid id,ChangeProcurementStatusRequest r,ProcurementContext c,CancellationToken t){var quote=await db.Quotations.AsSplitQuery().Include(x=>x.Lines).Include(x=>x.Rfq).ThenInclude(x=>x.Quotations).SingleOrDefaultAsync(x=>x.Id==id,t);if(quote is null)return NotFound<PurchaseOrderResponse>();if(quote.Status!=QuoteStatus.Received)return Conflict<PurchaseOrderResponse>("Only a received quotation can be selected.");var total=quote.Lines.Sum(x=>x.Quantity*x.UnitPrice);var route=await approvals.ResolveAsync("PurchaseOrder",total,t);if(route is null||route.Steps.Length==0)return Conflict<PurchaseOrderResponse>("No matching Purchase Order approval tier is configured.");quote.Status=QuoteStatus.Selected;foreach(var other in quote.Rfq.Quotations.Where(x=>x.Id!=id))other.Status=QuoteStatus.Rejected;var po=new PurchaseOrder{Id=Guid.NewGuid(),Number=numbers.PurchaseOrder(),RequisitionId=quote.Rfq.RequisitionId,QuotationId=quote.Id,VendorId=quote.VendorId,VendorName=quote.VendorName,Status=PoStatus.PendingApproval,CreatedAt=Now,CreatedBy=c.Actor};foreach(var l in quote.Lines)po.Lines.Add(new(){Id=Guid.NewGuid(),PurchaseOrderId=po.Id,ItemId=l.ItemId,Quantity=l.Quantity,UnitPrice=l.UnitPrice});foreach(var step in route.Steps)po.Approvals.Add(new(){Id=Guid.NewGuid(),PurchaseOrderId=po.Id,Sequence=step.Sequence,RequiredRole=step.RequiredRole});db.PurchaseOrders.Add(po);History("PurchaseOrder",po.Id,"None",po.Status.ToString(),r.Reason,c);return await Save(()=>Map(po),t);}
    public async Task<ProcurementResult<PurchaseOrderResponse>> DecideOrder(Guid id,bool approve,ChangeProcurementStatusRequest r,ProcurementContext c,CancellationToken t){var po=await db.PurchaseOrders.AsSplitQuery().Include(x=>x.Lines).Include(x=>x.Approvals).SingleOrDefaultAsync(x=>x.Id==id,t);if(po is null)return NotFound<PurchaseOrderResponse>();if(po.Status!=PoStatus.PendingApproval)return Conflict<PurchaseOrderResponse>("The order is not pending approval.");if(!Version(po.RowVersion,r.Version))return Conflict<PurchaseOrderResponse>("The purchase order changed. Reload and retry.");var next=po.Approvals.Where(x=>x.Decision=="Pending").OrderBy(x=>x.Sequence).First();if(!HasRole(c,next.RequiredRole))return Forbidden<PurchaseOrderResponse>($"The next approval requires role {next.RequiredRole}.");next.Decision=approve?"Approved":"Rejected";next.DecidedBy=c.Actor;next.DecidedAt=Now;next.Remarks=r.Reason;var old=po.Status;if(!approve)po.Status=PoStatus.Rejected;else if(po.Approvals.All(x=>x.Decision=="Approved"))po.Status=PoStatus.Approved;Touch(po,c);History("PurchaseOrder",po.Id,old.ToString(),po.Status.ToString(),r.Reason,c);return await Save(()=>Map(po),t);}
    public async Task<ProcurementResult<GoodsReceiptResponse>> CreateReceipt(Guid poId,CreateGoodsReceiptRequest r,ProcurementContext c,CancellationToken t){var po=await db.PurchaseOrders.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==poId,t);if(po is null)return NotFound<GoodsReceiptResponse>();if(po.Status is not (PoStatus.Approved or PoStatus.PartiallyReceived))return Conflict<GoodsReceiptResponse>("Goods can be received only against an approved purchase order.");if(r.Lines.Length==0||r.Lines.Any(x=>x.Quantity<=0||string.IsNullOrWhiteSpace(x.LotNumber)))return Validation<GoodsReceiptResponse>("Valid receipt lines are required.");var gr=new GoodsReceipt{Id=Guid.NewGuid(),Number=numbers.GoodsReceipt(),PurchaseOrderId=po.Id,SupplierReference=r.SupplierReference.Trim(),CreatedAt=Now,CreatedBy=c.Actor};foreach(var l in r.Lines){var pol=po.Lines.SingleOrDefault(x=>x.Id==l.PurchaseOrderLineId);if(pol is null||pol.ReceivedQuantity+l.Quantity>pol.Quantity)return Validation<GoodsReceiptResponse>("A receipt quantity exceeds its open purchase-order quantity.");var item=await catalog.GetItemAsync(pol.ItemId,t);if(item is null)return Validation<GoodsReceiptResponse>("A receipt item is unavailable in Catalog.");gr.Lines.Add(new(){Id=Guid.NewGuid(),GoodsReceiptId=gr.Id,PurchaseOrderLineId=pol.Id,ItemId=pol.ItemId,WarehouseId=l.WarehouseId,LotNumber=l.LotNumber.Trim(),ManufacturingDate=l.ManufacturingDate,ExpiryDate=l.ExpiryDate,Quantity=l.Quantity,Inspection=item.RequiresInspection?InspectionState.Pending:InspectionState.NotRequired});}gr.Status=gr.Lines.Any(x=>x.Inspection==InspectionState.Pending)?ReceiptStatus.PendingInspection:ReceiptStatus.Accepted;db.GoodsReceipts.Add(gr);if(gr.Status==ReceiptStatus.Accepted){var received=await inventory.ReceiveAsync(gr.Number,gr.Lines.Select(ToInventory).ToArray(),c.Actor,t);if(!received.Succeeded)return Conflict<GoodsReceiptResponse>(received.Errors);ApplyReceipt(po,gr);}History("GoodsReceipt",gr.Id,"None",gr.Status.ToString(),"Goods receipt recorded",c);return await Save(()=>Map(gr),t);}
    public async Task<ProcurementResult<GoodsReceiptResponse>> Inspect(Guid receiptId,Guid lineId,CompleteInspectionRequest r,ProcurementContext c,CancellationToken t){var gr=await db.GoodsReceipts.AsSplitQuery().Include(x=>x.Lines).ThenInclude(x=>x.InspectionResults).Include(x=>x.PurchaseOrder).ThenInclude(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==receiptId,t);if(gr is null)return NotFound<GoodsReceiptResponse>();if(gr.Status!=ReceiptStatus.PendingInspection)return Conflict<GoodsReceiptResponse>("This receipt is not awaiting inspection.");var line=gr.Lines.SingleOrDefault(x=>x.Id==lineId);if(line is null)return NotFound<GoodsReceiptResponse>();var item=await catalog.GetItemAsync(line.ItemId,t);if(item is null)return Conflict<GoodsReceiptResponse>("The Catalog inspection definition is unavailable.");var mandatory=item.Criteria.Where(x=>x.IsMandatory).Select(x=>x.Id);if(mandatory.Except(r.Results.Select(x=>x.CriterionId)).Any())return Validation<GoodsReceiptResponse>("All mandatory inspection criteria must be recorded.");line.Inspection=r.Results.All(x=>x.Passed)?InspectionState.Passed:InspectionState.Failed;foreach(var value in r.Results){var criterion=item.Criteria.SingleOrDefault(x=>x.Id==value.CriterionId);if(criterion is null)return Validation<GoodsReceiptResponse>("An inspection criterion is invalid.");db.Set<QualityInspectionResult>().Add(new(){Id=Guid.NewGuid(),GoodsReceiptLineId=line.Id,CriterionId=value.CriterionId,Criterion=criterion.Name,Result=value.Result.Trim(),Passed=value.Passed,Remarks=value.Remarks.Trim(),SupportingReference=value.SupportingReference.Trim(),Inspector=c.Actor,InspectedAt=Now});}if(gr.Lines.All(x=>x.Inspection is InspectionState.Passed or InspectionState.NotRequired)){var received=await inventory.ReceiveAsync(gr.Number,gr.Lines.Select(ToInventory).ToArray(),c.Actor,t);if(!received.Succeeded)return Conflict<GoodsReceiptResponse>(received.Errors);gr.Status=ReceiptStatus.Accepted;ApplyReceipt(gr.PurchaseOrder,gr);History("GoodsReceipt",gr.Id,"PendingInspection","Accepted",r.Remarks,c);}else if(gr.Lines.Any(x=>x.Inspection==InspectionState.Failed)){gr.Status=ReceiptStatus.Rejected;History("GoodsReceipt",gr.Id,"PendingInspection","Rejected",r.Remarks,c);}Touch(gr,c);return await Save(()=>Map(gr),t);}
    public async Task<ProcurementResult<VendorReturnResponse>> Return(CreateVendorReturnRequest r,ProcurementContext c,CancellationToken t)
    {
        if (string.IsNullOrWhiteSpace(r.Reason) || r.Reason.Length > 500 ||
            r.Lines is null || r.Lines.Length == 0 ||
            r.Lines.Select(x => x.GoodsReceiptLineId).Distinct().Count() != r.Lines.Length ||
            r.Lines.Any(x => x.GoodsReceiptLineId == Guid.Empty || x.Quantity <= 0 || x.Quantity != decimal.Round(x.Quantity, 3)))
            return Validation<VendorReturnResponse>("A reason and unique positive three-decimal return lines are required.");

        var gr = await db.GoodsReceipts.Include(x => x.Lines).SingleOrDefaultAsync(x => x.Id == r.GoodsReceiptId, t);
        if (gr is null) return NotFound<VendorReturnResponse>();
        if (gr.Status != ReceiptStatus.Accepted)
            return Conflict<VendorReturnResponse>("Only accepted stock can be returned to a vendor.");

        var previouslyReturned = await db.VendorReturns.AsNoTracking()
            .Where(x => x.GoodsReceiptId == gr.Id).SelectMany(x => x.Lines)
            .GroupBy(x => x.GoodsReceiptLineId)
            .Select(group => new { Id = group.Key, Quantity = group.Sum(x => x.Quantity) })
            .ToDictionaryAsync(x => x.Id, x => x.Quantity, t);
        var allocations = new List<ProcurementInventoryReturn>();
        foreach (var requested in r.Lines)
        {
            var line = gr.Lines.SingleOrDefault(x => x.Id == requested.GoodsReceiptLineId);
            if (line is null || requested.Quantity > line.Quantity - previouslyReturned.GetValueOrDefault(requested.GoodsReceiptLineId))
                return Validation<VendorReturnResponse>("The vendor-return quantity exceeds the unreturned receipt quantity.");
            allocations.Add(new(line.ItemId, line.WarehouseId, line.LotNumber, requested.Quantity));
        }

        var document = new VendorReturn
        {
            Id = Guid.NewGuid(), Number = numbers.VendorReturn(), GoodsReceiptId = gr.Id,
            Reason = r.Reason.Trim(), CreatedAt = Now, CreatedBy = c.Actor
        };
        foreach (var line in r.Lines)
            document.Lines.Add(new() { Id = Guid.NewGuid(), VendorReturnId = document.Id,
                GoodsReceiptLineId = line.GoodsReceiptLineId, Quantity = line.Quantity });
        var result = await inventory.ReturnAsync(document.Number, allocations.ToArray(), c.Actor, t);
        if (!result.Succeeded) return Conflict<VendorReturnResponse>(result.Errors);
        db.VendorReturns.Add(document);
        if (gr.Lines.All(line => previouslyReturned.GetValueOrDefault(line.Id) +
            r.Lines.Where(x => x.GoodsReceiptLineId == line.Id).Sum(x => x.Quantity) == line.Quantity))
        {
            gr.Status = ReceiptStatus.Returned;
            Touch(gr, c);
            History("GoodsReceipt", gr.Id, "Accepted", "Returned", document.Reason, c);
        }
        History("VendorReturn", document.Id, "None", "Completed", document.Reason, c);
        return await Save(() => new VendorReturnResponse(document.Id, document.Number, document.GoodsReceiptId,
            document.Reason, document.Lines.Sum(x => x.Quantity), document.CreatedAt, document.CreatedBy), t);
    }
    private static void ApplyReceipt(PurchaseOrder po,GoodsReceipt gr){foreach(var line in gr.Lines)po.Lines.Single(x=>x.Id==line.PurchaseOrderLineId).ReceivedQuantity+=line.Quantity;po.Status=po.Lines.All(x=>x.ReceivedQuantity==x.Quantity)?PoStatus.Received:PoStatus.PartiallyReceived;}
    private static ProcurementInventoryReceipt ToInventory(GoodsReceiptLine x)=>new(x.ItemId,x.WarehouseId,x.LotNumber,x.ManufacturingDate,x.ExpiryDate,x.Quantity);
    private static bool HasRole(ProcurementContext c,string required)=>c.Roles.Any(x=>string.Equals(x,required,StringComparison.OrdinalIgnoreCase))||c.Roles.Any(x=>x.Contains("Admin",StringComparison.OrdinalIgnoreCase));
    private void History(string type,Guid id,string old,string next,string reason,ProcurementContext c)=>db.StatusHistory.Add(new(){Id=Guid.NewGuid(),DocumentType=type,DocumentId=id,PreviousStatus=old,NewStatus=next,Reason=string.IsNullOrWhiteSpace(reason)?"Status updated":reason.Trim(),ChangedBy=c.Actor,ChangedAt=Now});
    private static string[] Validate(CreateRequisitionRequest r){var e=new List<string>();if(string.IsNullOrWhiteSpace(r.Department)||r.Department.Length>100)e.Add("A department is required.");if(string.IsNullOrWhiteSpace(r.Reason)||r.Reason.Length>500)e.Add("A reason is required.");if(r.Lines.Length==0||r.Lines.Any(x=>x.ItemId==Guid.Empty||x.Quantity<=0||x.EstimatedUnitPrice<0))e.Add("Every requisition line needs an item, positive quantity, and non-negative price.");if(r.Lines.Select(x=>x.ItemId).Distinct().Count()!=r.Lines.Length)e.Add("An item may appear only once.");return e.ToArray();}
    private async Task<ProcurementResult<T>> Save<T>(Func<T> map,CancellationToken t){try{await db.SaveChangesAsync(t);return ProcurementResult<T>.Success(map());}catch(DbUpdateConcurrencyException exception){LogConcurrency(logger,exception,string.Join(',',exception.Entries.Select(x=>x.Metadata.ClrType.Name)));return Conflict<T>("The record changed. Reload and retry.");}catch(DbUpdateException){return Conflict<T>("The procurement change conflicts with current data.");}}
    private static bool Version(byte[] current,string value){try{return current.Length==0&&Convert.FromBase64String(value).Length==0||current.SequenceEqual(Convert.FromBase64String(value));}catch(FormatException){return false;}}
    private void Touch(ProcurementDocument x,ProcurementContext c){x.ModifiedAt=Now;x.ModifiedBy=c.Actor;}
    private static RequisitionResponse Map(PurchaseRequisition x)=>new(x.Id,x.Number,x.Department,x.RequiredOn,x.Reason,(RequisitionStatus)x.Status,x.Lines.Sum(y=>y.Quantity*y.EstimatedUnitPrice),x.Lines.Select(y=>new RequisitionLineResponse(y.Id,y.ItemId,y.Quantity,y.EstimatedUnitPrice,y.Notes)).ToArray(),x.CreatedAt,x.CreatedBy,Convert.ToBase64String(x.RowVersion));
    private static RfqResponse Map(RequestForQuotation x)=>new(x.Id,x.Number,x.RequisitionId,x.ResponseDeadline,Enum.Parse<RfqStatus>(x.Status),x.Vendors.Select(y=>y.VendorId).ToArray(),x.CreatedAt,Convert.ToBase64String(x.RowVersion));
    private static QuotationResponse Map(VendorQuotation x)=>new(x.Id,x.RfqId,x.VendorId,x.VendorName,x.ValidUntil,x.Reference,(QuotationStatus)x.Status,x.Lines.Sum(y=>y.Quantity*y.UnitPrice),x.Lines.Select(y=>new QuotationLineResponse(y.Id,y.ItemId,y.Quantity,y.UnitPrice,y.LeadTimeDays)).ToArray(),x.CreatedAt,Convert.ToBase64String(x.RowVersion));
    private static PurchaseOrderResponse Map(PurchaseOrder x)=>new(x.Id,x.Number,x.RequisitionId,x.QuotationId,x.VendorId,x.VendorName,(PurchaseOrderStatus)x.Status,x.Lines.Sum(y=>y.Quantity*y.UnitPrice),x.Lines.Select(y=>new PurchaseOrderLineResponse(y.Id,y.ItemId,y.Quantity,y.UnitPrice,y.ReceivedQuantity)).ToArray(),x.Approvals.OrderBy(y=>y.Sequence).Select(y=>new ApprovalDecisionResponse(y.Id,y.Sequence,y.RequiredRole,y.Decision,y.DecidedBy,y.DecidedAt,y.Remarks)).ToArray(),x.CreatedAt,x.CreatedBy,Convert.ToBase64String(x.RowVersion));
    private static GoodsReceiptResponse Map(GoodsReceipt x,IReadOnlyDictionary<Guid,decimal>? returned=null)=>new(x.Id,x.Number,x.PurchaseOrderId,x.SupplierReference,(GoodsReceiptStatus)x.Status,x.Lines.Select(y=>new ReceiptLineResponse(y.Id,y.PurchaseOrderLineId,y.ItemId,y.WarehouseId,y.LotNumber,y.ManufacturingDate,y.ExpiryDate,y.Quantity,(InspectionDecision)y.Inspection,returned?.GetValueOrDefault(y.Id)??0m)).ToArray(),x.CreatedAt,x.CreatedBy,Convert.ToBase64String(x.RowVersion));
    private static ProcurementResult<T> Validation<T>(params string[]e)=>ProcurementResult<T>.Fail(ProcurementResultStatus.Validation,e);private static ProcurementResult<T> NotFound<T>()=>ProcurementResult<T>.Fail(ProcurementResultStatus.NotFound,"The procurement record was not found.");private static ProcurementResult<T> Conflict<T>(params string[]e)=>ProcurementResult<T>.Fail(ProcurementResultStatus.Conflict,e);private static ProcurementResult<T> Forbidden<T>(params string[]e)=>ProcurementResult<T>.Fail(ProcurementResultStatus.Forbidden,e);
}
